//! Writes a program in the IR as a WebAssembly module in the text format,
//! using the GC types the browser's collector manages.
//!
//! Every IR function becomes a Wasm function `$f<id>`. Expressions are
//! generated by [`Gen::expr`], which writes instructions that leave the
//! expression's value on the stack (nothing, for `Unit` and `Never`).
//! Control flow keeps the IR's tree shape: blocks, `if`s and loops become
//! Wasm blocks with named labels. The value representations, the slots of
//! generic code and the failing-call protocol are those of the C backend
//! (see `runtime/kiln.wat`), so both backends behave the same.

use kiln_check::types::substitute;
use kiln_diagnostics::{codes, Diagnostic, Span};
use kiln_ir::*;
use std::collections::{BTreeSet, HashMap};
use std::fmt::Write as _;

mod browser;
mod json;

/// A Wasm value type, as text, or `None` for `Unit` and `Never`, which
/// have no value.
type Wt = Option<String>;

#[derive(Clone, Default)]
struct LocalW {
    /// The Wasm local.
    name: String,
    /// For a local in a cell: the cell's type.
    cell: Option<&'static str>,
    /// The value's Wasm type.
    wt: Wt,
}

struct FnState {
    decls: String,
    body: String,
    locals: Vec<LocalW>,
    tys: Vec<Ty>,
    ret: Ty,
    closure: bool,
    /// The labels of the loops around: (break, continue).
    loops: Vec<(String, String)>,
}

impl Default for FnState {
    fn default() -> Self {
        FnState {
            decls: String::new(),
            body: String::new(),
            locals: Vec::new(),
            tys: Vec::new(),
            ret: Ty::Unit,
            closure: false,
            loops: Vec::new(),
        }
    }
}

/// What the module's functions are reached from.
pub enum Roots {
    /// The program's `main`, run once (for tests and `--target wasm`).
    Main,
    /// Functions the module exports by name, such as an ember's mount.
    Exports(Vec<(String, FuncId)>),
}

pub(crate) struct Gen<'a> {
    p: &'a Program,
    prims: Prims,
    pub diags: Vec<Diagnostic>,
    imports: String,
    types: String,
    globals: String,
    helpers: String,
    bodies: String,
    pub strings: Vec<String>,
    string_ids: HashMap<String, usize>,
    helper_names: HashMap<String, String>,
    funcrefs: BTreeSet<String>,
    counter: usize,
    f: FnState,
    ui: Option<AdtId>,
    js_value: Option<AdtId>,
    /// For each function: whether it is compiled, and the function it is
    /// first reached from.
    pub reached: Vec<bool>,
    via: Vec<Option<FuncId>>,
    /// Globals some compiled function reads.
    used_globals: Vec<bool>,
    /// Hosts the backend's extra imports (JSON, the DOM and so on).
    extra_imports: BTreeSet<String>,
    /// Whether this is a page's embers, where `server fn`s run on the
    /// server, rather than a whole program.
    browser: bool,
}

const RUNTIME_WAT: &str = include_str!("../runtime/kiln.wat");

/// The strings the runtime uses, given by `kiln.js` as module `r`.
const RUNTIME_STRINGS: &[&str] = &[
    "true", "false", "empty", "lbracket", "rbracket", "comma", "lbrace", "rbrace", "colon",
];

impl<'a> Gen<'a> {
    pub fn new(p: &'a Program) -> Self {
        let ui = (0..p.std_adts).find(|&id| p.adts[id].name == "Ui" && p.builtin[id]);
        // `js.Value` is a JavaScript value, held as a string is.
        let js_value = (0..p.std_adts).find(|&id| {
            p.adts[id].name == "Value"
                && matches!(&p.adts[id].kind, AdtKind::Struct(f) if f.is_empty())
        });
        Gen {
            p,
            prims: p.prims,
            diags: Vec::new(),
            imports: String::new(),
            types: String::new(),
            globals: String::new(),
            helpers: String::new(),
            bodies: String::new(),
            strings: Vec::new(),
            string_ids: HashMap::new(),
            helper_names: HashMap::new(),
            funcrefs: BTreeSet::new(),
            counter: 0,
            f: FnState::default(),
            ui,
            js_value,
            reached: vec![false; p.funcs.len()],
            via: vec![None; p.funcs.len()],
            used_globals: vec![false; p.globals.len()],
            extra_imports: BTreeSet::new(),
            browser: false,
        }
    }

    // ----- the module -----

    pub fn module(&mut self, roots: &Roots) -> String {
        let root_ids: Vec<FuncId> = match roots {
            Roots::Main => vec![self.p.main],
            Roots::Exports(list) => list.iter().map(|(_, f)| *f).collect(),
        };
        self.browser = matches!(roots, Roots::Exports(_));
        self.reach(&root_ids);
        self.struct_types();
        for (i, g) in self.p.globals.iter().enumerate() {
            if !self.used_globals[i] {
                continue;
            }
            let wt = self.wt(&g.ty);
            if let Some(wt) = wt {
                let init = default_value(&wt);
                let _ = writeln!(self.globals, "  (global $g{i} (mut {wt}) ({init}))");
            }
        }
        for i in 0..self.p.stores.len() {
            let _ = writeln!(
                self.globals,
                "  (global $st{i} (mut (ref null $Opt)) (ref.null $Opt))"
            );
        }
        // The stores that `stores.scope` put aside.
        self.types.push_str(
            "  (type $StArr (array (mut (ref null $Opt))))\n  (rec (type $StSave (struct (field (ref null $StSave)) (field (ref $StArr)))))\n",
        );
        self.globals
            .push_str("  (global $st_saved (mut (ref null $StSave)) (ref.null $StSave))\n");
        if self.browser && !self.p.stores.is_empty() {
            self.extra_imports
                .insert("  (import \"b\" \"store_read\" (func $b_store_read (param i32)))".into());
        }
        for id in 0..self.p.funcs.len() {
            if self.reached[id] && id != self.p.init {
                self.function(id);
            }
        }
        self.init_function();
        let mut exports = String::new();
        match roots {
            Roots::Main => {
                let _ = write!(
                    exports,
                    "  (func (export \"main\")\n    (call $init)\n    (call $f{})\n    (call $k_exit_failed))\n",
                    self.p.main
                );
            }
            Roots::Exports(list) => {
                exports.push_str("  (func (export \"init\") (call $init))\n");
                for (name, id) in list {
                    let _ = writeln!(exports, "  (export {} (func $f{id}))", wat_string(name));
                }
            }
        }
        let (head, rest) = RUNTIME_WAT
            .split_once("  ;; ----- definitions -----")
            .expect("the runtime marks where its definitions start");
        let mut out = String::from("(module\n");
        out.push_str(head);
        for name in RUNTIME_STRINGS {
            let _ = writeln!(
                out,
                "  (import \"r\" \"{name}\" (global $s_{name} externref))"
            );
        }
        for imp in &self.extra_imports {
            out.push_str(imp);
            out.push('\n');
        }
        out.push_str(&self.imports);
        out.push_str(&self.types);
        out.push_str(rest);
        out.push_str(EXIT_FAILED);
        // Functions the runtime itself uses as values.
        for part in rest.split("ref.func ").skip(1) {
            let name: String = part
                .chars()
                .take_while(|c| !c.is_whitespace() && *c != ')')
                .collect();
            self.funcrefs.insert(name);
        }
        out.push_str(&self.globals);
        if !self.funcrefs.is_empty() {
            out.push_str("  (elem declare func");
            for f in &self.funcrefs {
                out.push(' ');
                out.push_str(f);
            }
            out.push_str(")\n");
        }
        out.push_str(&self.helpers);
        out.push_str(&self.bodies);
        out.push_str(&exports);
        out.push_str(")\n");
        out
    }

    /// Marks the functions reachable from `roots`, and the globals they
    /// read, following the initializers of those globals too.
    fn reach(&mut self, roots: &[FuncId]) {
        let mut work: Vec<FuncId> = Vec::new();
        for &r in roots {
            if !self.reached[r] {
                self.reached[r] = true;
                work.push(r);
            }
        }
        // The initializer of each global, in `init`.
        let mut inits: HashMap<GlobalId, &Expr> = HashMap::new();
        for stmt in &self.p.funcs[self.p.init].body.stmts {
            if let Stmt::SetGlobal(g, e) = stmt {
                inits.insert(*g, e);
            }
        }
        loop {
            while let Some(f) = work.pop() {
                let mut found = Refs::default();
                walk_block(&self.p.funcs[f].body, &mut found);
                self.add_refs(found, Some(f), &mut work);
            }
            let mut more = Refs::default();
            for (g, used) in self.used_globals.iter().enumerate() {
                if *used {
                    if let Some(e) = inits.get(&g) {
                        walk_expr(e, &mut more);
                    }
                }
            }
            let before = self.used_globals.iter().filter(|u| **u).count();
            self.add_refs(more, Some(self.p.init), &mut work);
            let after = self.used_globals.iter().filter(|u| **u).count();
            if work.is_empty() && before == after {
                break;
            }
        }
    }

    fn add_refs(&mut self, refs: Refs, from: Option<FuncId>, work: &mut Vec<FuncId>) {
        for f in refs.funcs {
            // A page's embers call `server fn`s over the network.
            if self.browser && self.p.funcs[f].server {
                continue;
            }
            if !self.reached[f] {
                self.reached[f] = true;
                self.via[f] = from;
                work.push(f);
            }
        }
        for g in refs.globals {
            self.used_globals[g] = true;
        }
    }

    /// The type of every struct with fields, in one recursion group so that
    /// structs can refer to each other.
    fn struct_types(&mut self) {
        let mut group = String::new();
        for id in 0..self.p.adts.len() {
            if self.p.is_prim(id) {
                continue;
            }
            if let AdtKind::Struct(fields) = &self.p.adts[id].kind {
                if fields.is_empty() {
                    continue;
                }
                let _ = write!(group, "    (type $S{id} (struct");
                for f in fields {
                    let wt = self.wt(&f.ty).unwrap_or_else(|| "i32".into());
                    let _ = write!(group, " (field (mut {wt}))");
                }
                group.push_str("))\n");
            }
        }
        if !group.is_empty() {
            let _ = write!(self.types, "  (rec\n{group}  )\n");
        }
    }

    fn init_function(&mut self) {
        self.f = FnState {
            ret: Ty::Unit,
            ..FnState::default()
        };
        let init = &self.p.funcs[self.p.init];
        for (i, local) in init.locals.iter().enumerate() {
            self.declare_local(i, local, false);
        }
        for stmt in &init.body.stmts {
            if let Stmt::SetGlobal(g, _) = stmt {
                if !self.used_globals[*g] {
                    continue;
                }
            }
            self.stmt(stmt);
        }
        let f = std::mem::take(&mut self.f);
        let _ = write!(self.bodies, "  (func $init\n{}{}  )\n", f.decls, f.body);
    }

    fn declare_local(&mut self, i: usize, local: &Local, param: bool) -> String {
        let name = format!("$l{i}");
        let wt = self.wt(&local.ty);
        let cell = if local.cell {
            Some(cell_type(wt.as_deref()))
        } else {
            None
        };
        let decl = match (cell, &wt) {
            (Some(c), _) => Some(format!("(ref null {c})")),
            (None, Some(w)) => Some(w.clone()),
            (None, None) => None,
        };
        let mut sig = String::new();
        if let Some(d) = decl {
            if param && cell.is_none() {
                sig = format!("(param {name} {d})");
            } else {
                let _ = writeln!(self.f.decls, "    (local {name} {d})");
                if param {
                    // A captured parameter: it arrives as a value and is
                    // moved into its cell.
                    let _ = writeln!(
                        self.f.decls,
                        "    (local {name}_v {})",
                        wt.clone().unwrap_or_default()
                    );
                    sig = format!("(param {name}_v {})", wt.clone().unwrap_or_default());
                }
            }
        }
        self.f.locals.push(LocalW { name, cell, wt });
        sig
    }

    fn function(&mut self, id: FuncId) {
        let func = &self.p.funcs[id];
        let closure = func.kind == FuncKind::Closure;
        self.f = FnState {
            ret: func.ret.clone(),
            closure,
            tys: func.locals.iter().map(|l| l.ty.clone()).collect(),
            ..FnState::default()
        };
        let mut params = Vec::new();
        for (i, local) in func.locals.iter().enumerate() {
            let param = !closure && func.params.contains(&i);
            let sig = self.declare_local(i, local, param);
            if param {
                params.push((i, sig));
            }
        }
        // Parameters in order.
        params.sort_by_key(|(i, _)| func.params.iter().position(|p| p == i));
        let mut header = format!("  (func $f{id}");
        if closure {
            header.push_str(" (type $Code) (param $env (ref null $Slots)) (param $args (ref null $Slots)) (result anyref)");
            for (i, &l) in func.captures.iter().enumerate() {
                let lw = self.f.locals[l].clone();
                self.line(&format!(
                    "(array.get $Slots (local.get $env) (i32.const {i}))"
                ));
                match lw.cell {
                    Some(c) => self.line(&format!("(ref.cast (ref null {c}))")),
                    None => self.unslot(&func.locals[l].ty.clone()),
                }
                if lw.cell.is_some() || lw.wt.is_some() {
                    self.line(&format!("local.set {}", lw.name));
                } else {
                    self.line("drop");
                }
            }
            for (i, &l) in func.params.iter().enumerate() {
                let ty = func.locals[l].ty.clone();
                self.line(&format!(
                    "(array.get $Slots (local.get $args) (i32.const {i}))"
                ));
                self.unslot(&ty);
                self.init_local(l);
            }
        } else {
            for (_, sig) in &params {
                if !sig.is_empty() {
                    header.push(' ');
                    header.push_str(sig);
                }
            }
            if let Some(wt) = self.wt(&func.ret) {
                let _ = write!(header, " (result {wt})");
            }
            // Captured parameters move into their cells.
            for &l in &func.params {
                let lw = self.f.locals[l].clone();
                if lw.cell.is_some() {
                    self.line(&format!("local.get {}_v", lw.name));
                    self.init_local(l);
                }
            }
        }
        let has_value = self.wt(&func.ret).is_some();
        self.block(&func.body, has_value || closure);
        let value_ty = block_ty(&func.body);
        if closure {
            if self.wt(&value_ty).is_some() {
                self.convert(&value_ty, &func.ret);
                self.in_slot(&func.ret);
            } else if matches!(value_ty, Ty::Never) {
                self.line("unreachable");
            } else {
                self.line("ref.null any");
            }
        } else if has_value {
            if self.wt(&value_ty).is_some() {
                self.convert(&value_ty, &func.ret);
            } else {
                self.line("unreachable");
            }
        }
        let f = std::mem::take(&mut self.f);
        let _ = write!(self.bodies, "{header}\n{}{}  )\n", f.decls, f.body);
    }

    // ----- types -----

    fn is_adt(&self, ty: &Ty, id: AdtId) -> bool {
        matches!(ty, Ty::Adt(i, _) if *i == id)
    }

    fn is_string(&self, ty: &Ty) -> bool {
        self.is_adt(ty, self.prims.string)
            || self.ui.is_some_and(|u| self.is_adt(ty, u))
            || self.js_value.is_some_and(|v| self.is_adt(ty, v))
    }

    pub fn wt(&self, ty: &Ty) -> Wt {
        let p = self.prims;
        Some(
            match ty {
                Ty::Unit | Ty::Never => return None,
                _ if self.is_string(ty) => "externref",
                Ty::Adt(id, _) if *id == p.int || *id == p.duration => "i64",
                Ty::Adt(id, _) if *id == p.float => "f64",
                Ty::Adt(id, _) if *id == p.bool_ => "i32",
                Ty::Adt(id, _) if *id == p.list => "(ref null $List)",
                Ty::Adt(id, _) if *id == p.map || *id == p.set => "(ref null $Map)",
                Ty::Adt(id, _) if self.p.is_prim(*id) => "anyref",
                Ty::Adt(id, _) => match &self.p.adts[*id].kind {
                    AdtKind::Enum(_) => "(ref null $Enum)",
                    AdtKind::Struct(f) if f.is_empty() => "(ref null $Empty)",
                    AdtKind::Struct(_) => return Some(format!("(ref null $S{id})")),
                },
                Ty::Opt(_) => "(ref null $Opt)",
                Ty::Fn(_) => "(ref null $Closure)",
                Ty::Record(_) => "(ref null $Slots)",
                _ => "anyref",
            }
            .to_string(),
        )
    }

    /// Whether values of `ty` live in slots as they are (generic values).
    fn is_slot(&self, ty: &Ty) -> bool {
        self.wt(ty).as_deref() == Some("anyref")
    }

    /// The value on the stack, of type `ty`, moved into a slot.
    fn in_slot(&mut self, ty: &Ty) {
        match self.wt(ty).as_deref() {
            None => self.line("ref.null any"),
            Some("i64") => self.line("struct.new $BoxI64"),
            Some("f64") => self.line("struct.new $BoxF64"),
            Some("i32") => self.line("ref.i31"),
            Some("externref") => self.line("any.convert_extern"),
            _ => {}
        }
    }

    /// The slot on the stack read back as a value of type `ty`.
    fn unslot(&mut self, ty: &Ty) {
        match self.wt(ty).as_deref() {
            None => self.line("drop"),
            Some("i64") => self.line("call $k_i64"),
            Some("f64") => self.line("call $k_f64"),
            Some("i32") => self.line("call $k_i32"),
            Some("externref") => self.line("extern.convert_any"),
            Some("anyref") => {}
            Some(r) => {
                let r = r.to_string();
                self.line(&format!("ref.cast {r}"));
            }
        }
    }

    /// Converts the value on the stack from type `from` to the
    /// representation of `to`: into or out of a slot, or into an optional.
    fn convert(&mut self, from: &Ty, to: &Ty) {
        if matches!(from, Ty::Never | Ty::Unknown) || matches!(to, Ty::Never | Ty::Unknown) {
            return;
        }
        let (fw, tw) = (self.wt(from), self.wt(to));
        if tw.is_none() {
            if fw.is_some() {
                self.line("drop");
            }
            return;
        }
        if fw.is_none() {
            // A unit value where a value is expected, as in a slot.
            self.line(&default_value(tw.as_deref().unwrap_or("anyref")));
            return;
        }
        if matches!(to, Ty::Opt(inner) if **inner == *from) {
            self.in_slot(from);
            self.line("call $k_box");
            return;
        }
        if self.is_slot(to) {
            if !self.is_slot(from) {
                self.in_slot(from);
            }
            return;
        }
        if self.is_slot(from) {
            self.unslot(to);
            return;
        }
        if matches!(to, Ty::Opt(_)) && !matches!(from, Ty::Opt(_)) {
            self.in_slot(from);
            self.line("call $k_box");
        }
    }

    fn type_map(&self, id: AdtId, args: &[Ty]) -> HashMap<String, Ty> {
        self.p.adts[id]
            .params
            .iter()
            .cloned()
            .zip(args.iter().cloned())
            .collect()
    }

    // ----- output -----

    fn next(&mut self) -> usize {
        self.counter += 1;
        self.counter
    }

    fn line(&mut self, s: &str) {
        self.f.body.push_str("    ");
        self.f.body.push_str(s);
        self.f.body.push('\n');
    }

    fn tmp(&mut self, wt: &str) -> String {
        let name = format!("$t{}", self.next());
        let _ = writeln!(self.f.decls, "    (local {name} {wt})");
        name
    }

    fn tmp_ty(&mut self, ty: &Ty) -> Option<String> {
        let wt = self.wt(ty)?;
        Some(self.tmp(&wt))
    }

    fn label(&mut self, prefix: &str) -> String {
        format!("${prefix}{}", self.next())
    }

    /// A string constant, as a global the JavaScript side gives.
    fn str_const(&mut self, s: &str) -> String {
        let id = match self.string_ids.get(s) {
            Some(&id) => id,
            None => {
                let id = self.strings.len();
                self.strings.push(s.to_string());
                self.string_ids.insert(s.to_string(), id);
                let _ = writeln!(
                    self.imports,
                    "  (import \"s\" \"{id}\" (global $c{id} externref))"
                );
                id
            }
        };
        format!("global.get $c{id}")
    }

    fn funcref(&mut self, name: &str) -> String {
        self.funcrefs.insert(name.to_string());
        format!("ref.func {name}")
    }

    /// The E0401 message for `what` done with values of `ty`, naming
    /// `Bytes`, which the browser does not have yet.
    pub(crate) fn not_compiled(&self, ty: &Ty, what: &str) -> String {
        if self.is_adt(ty, self.prims.bytes) {
            "`Bytes` values are not supported in the browser yet".to_string()
        } else if what.contains("JSON") {
            format!("{what} is not supported in the browser yet")
        } else {
            format!("{what} is not supported by the compiler yet")
        }
    }

    pub fn unsupported(&mut self, span: Span, what: impl Into<String>) {
        self.diags.push(
            Diagnostic::error(
                codes::NOT_COMPILED_YET,
                format!("{} is not supported in the browser yet", what.into()),
                span,
            )
            .with_help("embers run in the browser as WebAssembly, which cannot do this yet"),
        );
        self.line("unreachable");
    }

    pub fn server_only(&mut self, span: Span, what: &str) {
        self.diags.push(
            Diagnostic::error(
                codes::SERVER_ONLY,
                format!("{what} runs only on the server, so the browser cannot run it"),
                span,
            )
            .with_help("do this in a `server fn`, and call that from the ember"),
        );
        self.line("unreachable");
    }

    /// Leaves the current function after an error.
    fn fail_return(&mut self) {
        if self.f.closure {
            self.line("ref.null any");
        } else if let Some(wt) = self.wt(&self.f.ret.clone()) {
            self.line(&default_value(&wt));
        }
        self.line("return");
    }

    // ----- locals -----

    /// Pushes the value of local `l`.
    fn get_local(&mut self, l: LocalId) {
        let lw = self.f.locals[l].clone();
        let Some(wt) = &lw.wt else { return };
        match lw.cell {
            Some(c) => {
                self.line(&format!("local.get {}", lw.name));
                self.line(&format!("struct.get {c} 0"));
                if c == "$CellAny" && wt != "anyref" {
                    self.line(&format!("ref.cast {wt}"));
                }
            }
            None => self.line(&format!("local.get {}", lw.name)),
        }
    }

    /// Stores the value on the stack in local `l`, in a new cell when it
    /// has one.
    fn init_local(&mut self, l: LocalId) {
        let lw = self.f.locals[l].clone();
        if lw.wt.is_none() {
            return;
        }
        if let Some(c) = lw.cell {
            self.line(&format!("struct.new {c}"));
        }
        self.line(&format!("local.set {}", lw.name));
    }

    // ----- statements -----

    /// Generates a block. With `want`, its value is left on the stack;
    /// otherwise it is dropped.
    fn block(&mut self, b: &Block, want: bool) {
        for stmt in &b.stmts {
            self.stmt(stmt);
        }
        match &b.value {
            Some(v) if want => self.expr(v),
            Some(v) => self.discard(v),
            None => {}
        }
    }

    fn discard(&mut self, e: &Expr) {
        self.expr(e);
        if self.wt(&e.ty).is_some() {
            self.line("drop");
        }
    }

    fn stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Let(l, value) => {
                self.expr(value);
                let lt = self.f.tys[*l].clone();
                self.convert(&value.ty, &lt);
                if self.wt(&lt).is_none() {
                    return;
                }
                self.init_local(*l);
            }
            Stmt::SetGlobal(g, value) => {
                self.expr(value);
                if self.wt(&self.p.globals[*g].ty).is_some() {
                    self.line(&format!("global.set $g{g}"));
                }
            }
            Stmt::SetStore(id, value) => {
                self.expr(value);
                self.line(&format!("global.set $st{id}"));
            }
            Stmt::Assign { place, op, value } => self.assign(place, *op, value),
            Stmt::Return(value) => {
                let ret = self.f.ret.clone();
                if let Some(v) = value {
                    self.expr(v);
                    self.convert(&v.ty, &ret);
                }
                if self.f.closure {
                    if value.is_some() && self.wt(&ret).is_some() {
                        self.in_slot(&ret);
                    } else {
                        self.line("ref.null any");
                    }
                }
                self.line("return");
            }
            Stmt::Break => {
                let (brk, _) = self.f.loops.last().cloned().unwrap_or_default();
                self.line(&format!("br {brk}"));
            }
            Stmt::Continue => {
                let (_, cont) = self.f.loops.last().cloned().unwrap_or_default();
                self.line(&format!("br {cont}"));
            }
            Stmt::While { cond, body } => {
                let brk = self.label("brk");
                let cont = self.label("cont");
                self.line(&format!("block {brk}"));
                self.line(&format!("loop {cont}"));
                self.expr(cond);
                self.line("i32.eqz");
                self.line(&format!("br_if {brk}"));
                self.f.loops.push((brk.clone(), cont.clone()));
                self.block(body, false);
                self.f.loops.pop();
                self.line(&format!("br {cont}"));
                self.line("end");
                self.line("end");
            }
            Stmt::ForRange {
                var,
                lo,
                hi,
                filter,
                body,
            } => {
                let i = self.tmp("i64");
                let h = self.tmp("i64");
                self.expr(lo);
                self.line(&format!("local.set {i}"));
                self.expr(hi);
                self.line(&format!("local.set {h}"));
                let int = Ty::Adt(self.prims.int, Vec::new());
                let vt = self.f.tys[*var].clone();
                self.loop_over(
                    |g| {
                        g.line(&format!("local.get {i}"));
                        g.line(&format!("local.get {h}"));
                        g.line("i64.ge_s");
                    },
                    |g| {
                        g.line(&format!("local.get {i}"));
                        g.convert(&int, &vt);
                        g.init_local(*var);
                    },
                    |g| {
                        g.line(&format!("local.get {i}"));
                        g.line("i64.const 1");
                        g.line("i64.add");
                        g.line(&format!("local.set {i}"));
                    },
                    filter.as_ref(),
                    body,
                );
            }
            Stmt::ForEach {
                var,
                iter,
                filter,
                body,
            } => {
                let (elem, is_set) = match &iter.ty {
                    Ty::Adt(id, args) if !args.is_empty() => {
                        (args[0].clone(), *id == self.prims.set)
                    }
                    _ => (Ty::Unknown, false),
                };
                self.expr(iter);
                if is_set {
                    self.line("i32.const 0");
                    self.line("call $k_map_list");
                }
                let l = self.tmp("(ref null $List)");
                self.line(&format!("local.set {l}"));
                let i = self.tmp("i32");
                let vt = self.f.tys[*var].clone();
                self.loop_over(
                    |g| {
                        g.line(&format!("local.get {i}"));
                        g.line(&format!("(struct.get $List 0 (local.get {l}))"));
                        g.line("i32.ge_s");
                    },
                    |g| {
                        g.line(&format!("(call $k_item (local.get {l}) (local.get {i}))"));
                        g.unslot(&elem);
                        g.convert(&elem, &vt);
                        g.init_local(*var);
                    },
                    |g| {
                        g.line(&format!("local.get {i}"));
                        g.line("i32.const 1");
                        g.line("i32.add");
                        g.line(&format!("local.set {i}"));
                    },
                    filter.as_ref(),
                    body,
                );
            }
            Stmt::Expr(e) => self.discard(e),
        }
    }

    /// A counted loop: `done` pushes whether to stop, `bind` sets the loop
    /// variable, and `step` moves on, also after `continue`.
    fn loop_over(
        &mut self,
        done: impl FnOnce(&mut Self),
        bind: impl FnOnce(&mut Self),
        step: impl FnOnce(&mut Self),
        filter: Option<&Expr>,
        body: &Block,
    ) {
        let brk = self.label("brk");
        let top = self.label("top");
        let cont = self.label("cont");
        self.line(&format!("block {brk}"));
        self.line(&format!("loop {top}"));
        done(self);
        self.line(&format!("br_if {brk}"));
        bind(self);
        self.line(&format!("block {cont}"));
        if let Some(f) = filter {
            self.expr(f);
            self.line("i32.eqz");
            self.line(&format!("br_if {cont}"));
        }
        self.f.loops.push((brk.clone(), cont.clone()));
        self.block(body, false);
        self.f.loops.pop();
        self.line("end");
        step(self);
        self.line(&format!("br {top}"));
        self.line("end");
        self.line("end");
    }

    fn assign(&mut self, place: &Place, op: Option<ArithOp>, value: &Expr) {
        match place {
            Place::Local(l) => {
                let ty = self.f.tys[*l].clone();
                let lw = self.f.locals[*l].clone();
                if lw.wt.is_none() {
                    self.discard(value);
                    return;
                }
                if let Some(c) = lw.cell {
                    self.line(&format!("local.get {}", lw.name));
                    self.compound(op, |g| g.get_local(*l), value, &ty);
                    self.line(&format!("struct.set {c} 0"));
                } else {
                    self.compound(op, |g| g.get_local(*l), value, &ty);
                    self.line(&format!("local.set {}", lw.name));
                }
            }
            Place::Field { base, field, ty } => {
                let bw = self.wt(&base.ty).unwrap_or_else(|| "anyref".into());
                let b = self.tmp(&bw);
                self.expr(base);
                self.line(&format!("local.set {b}"));
                match &base.ty {
                    Ty::Adt(id, _) => {
                        let id = *id;
                        let decl = match &self.p.adts[id].kind {
                            AdtKind::Struct(fs) => fs[*field].ty.clone(),
                            AdtKind::Enum(_) => Ty::Unknown,
                        };
                        self.line(&format!("local.get {b}"));
                        self.compound(
                            op,
                            |g| {
                                g.line(&format!("local.get {b}"));
                                g.line(&format!("struct.get $S{id} {field}"));
                                g.convert(&decl, ty);
                            },
                            value,
                            ty,
                        );
                        self.convert(ty, &decl);
                        self.line(&format!("struct.set $S{id} {field}"));
                    }
                    _ => {
                        self.line(&format!("local.get {b}"));
                        self.line(&format!("i32.const {field}"));
                        let any = Ty::Any;
                        self.compound(
                            op,
                            |g| {
                                g.line(&format!("local.get {b}"));
                                g.line(&format!("i32.const {field}"));
                                g.line("array.get $Slots");
                                g.convert(&any, ty);
                            },
                            value,
                            ty,
                        );
                        self.convert(ty, &any);
                        self.line("array.set $Slots");
                    }
                }
            }
            Place::ListItem { list, index, ty } => {
                let l = self.tmp("(ref null $List)");
                let i = self.tmp("i64");
                self.expr(list);
                self.line(&format!("local.set {l}"));
                self.expr(index);
                self.line(&format!("local.set {i}"));
                self.line(&format!("local.get {l}"));
                self.line(&format!("local.get {i}"));
                self.compound(
                    op,
                    |g| {
                        g.line(&format!(
                            "(call $k_list_at (local.get {l}) (local.get {i}))"
                        ));
                        g.unslot(ty);
                    },
                    value,
                    ty,
                );
                self.in_slot(ty);
                self.line("call $k_list_set");
            }
            Place::MapEntry { map, key } => {
                let (kt, vt) = match &map.ty {
                    Ty::Adt(_, args) if args.len() == 2 => (args[0].clone(), args[1].clone()),
                    _ => (Ty::Unknown, Ty::Unknown),
                };
                let m = self.tmp("(ref null $Map)");
                let k = self.tmp("anyref");
                self.expr(map);
                self.line(&format!("local.set {m}"));
                self.expr(key);
                self.in_slot(&kt);
                self.line(&format!("local.set {k}"));
                self.line(&format!("local.get {m}"));
                self.line(&format!("local.get {k}"));
                self.compound(
                    op,
                    |g| {
                        g.line(&format!("(call $k_map_at (local.get {m}) (local.get {k}))"));
                        g.unslot(&vt);
                    },
                    value,
                    &vt,
                );
                self.in_slot(&vt);
                self.line("call $k_map_set");
            }
        }
    }

    /// Pushes the new value of a place: `value`, or with an operator the
    /// current value (pushed by `cur`) combined with it.
    fn compound(
        &mut self,
        op: Option<ArithOp>,
        cur: impl FnOnce(&mut Self),
        value: &Expr,
        ty: &Ty,
    ) {
        match op {
            None => {
                self.expr(value);
                self.convert(&value.ty, ty);
            }
            Some(op) => {
                cur(self);
                self.expr(value);
                self.convert(&value.ty, ty);
                self.arith(op, ty);
            }
        }
    }

    fn arith(&mut self, op: ArithOp, ty: &Ty) {
        if self.is_string(ty) {
            self.line("call $k_concat");
            return;
        }
        if self.wt(ty).as_deref() == Some("f64") {
            self.line(match op {
                ArithOp::Add => "f64.add",
                ArithOp::Sub => "f64.sub",
                ArithOp::Mul => "f64.mul",
                ArithOp::Div => "f64.div",
                ArithOp::Rem => "call $k_float_rem",
            });
            return;
        }
        self.line(match op {
            ArithOp::Add => "call $k_add",
            ArithOp::Sub => "call $k_sub",
            ArithOp::Mul => "call $k_mul",
            ArithOp::Div => "call $k_div",
            ArithOp::Rem => "call $k_rem",
        });
    }

    // ----- expressions -----

    fn expr(&mut self, e: &Expr) {
        self.expr_kind(e);
        if matches!(e.ty, Ty::Never) {
            self.line("unreachable");
        }
    }

    fn expr_kind(&mut self, e: &Expr) {
        match &e.kind {
            ExprKind::Int(n) => {
                if self.wt(&e.ty).as_deref() == Some("f64") {
                    self.line(&format!("f64.const {}", *n as f64));
                } else {
                    self.line(&format!("i64.const {n}"));
                }
            }
            ExprKind::Float(x) => self.line(&format!("f64.const {}", wat_float(*x))),
            ExprKind::Bool(b) => self.line(&format!("i32.const {}", i32::from(*b))),
            ExprKind::Str(s) => {
                let c = self.str_const(s);
                self.line(&c);
            }
            ExprKind::None => {
                let wt = self.wt(&e.ty).unwrap_or_else(|| "(ref null $Opt)".into());
                self.line(&default_value(&wt));
            }
            ExprKind::Local(l) => self.get_local(*l),
            ExprKind::Global(g) => {
                if self.wt(&self.p.globals[*g].ty).is_some() {
                    self.line(&format!("global.get $g{g}"));
                }
            }
            // A page's stores are one per page; the bridge learns which
            // stores an ember reads as it renders.
            ExprKind::StoreSlot(id) => {
                if self.browser {
                    self.line(&format!("i32.const {id}"));
                    self.line("call $b_store_read");
                }
                self.line(&format!("global.get $st{id}"));
            }
            ExprKind::FuncRef(f) => self.fn_value(*f),
            ExprKind::Concat(parts) => {
                if parts.is_empty() {
                    self.line("global.get $s_empty");
                }
                for (i, p) in parts.iter().enumerate() {
                    self.expr(p);
                    if i > 0 {
                        self.line("call $k_concat");
                    }
                }
            }
            ExprKind::Show(v) => {
                self.expr(v);
                self.display(&v.ty, v.span);
            }
            ExprKind::Not(v) => {
                self.expr(v);
                self.line("i32.eqz");
            }
            ExprKind::Neg(v) => {
                if self.wt(&e.ty).as_deref() == Some("f64") {
                    self.expr(v);
                    self.line("f64.neg");
                } else {
                    self.expr(v);
                    self.line("call $k_neg");
                }
            }
            ExprKind::Arith(op, a, b) => {
                self.expr(a);
                self.convert(&a.ty, &e.ty);
                self.expr(b);
                self.convert(&b.ty, &e.ty);
                self.arith(*op, &e.ty);
            }
            ExprKind::Cmp(op, a, b) => {
                self.expr(a);
                self.expr(b);
                let (s, i, f) = match op {
                    CmpOp::Lt => ("i32.lt_s", "i64.lt_s", "f64.lt"),
                    CmpOp::Le => ("i32.le_s", "i64.le_s", "f64.le"),
                    CmpOp::Gt => ("i32.gt_s", "i64.gt_s", "f64.gt"),
                    CmpOp::Ge => ("i32.ge_s", "i64.ge_s", "f64.ge"),
                };
                if self.is_string(&a.ty) {
                    self.line("call $k_str_cmp");
                    self.line("i32.const 0");
                    self.line(s);
                } else {
                    match self.wt(&a.ty).as_deref() {
                        Some("f64") => self.line(f),
                        Some("i32") => self.line(&s.replace("_s", "_u")),
                        _ => self.line(i),
                    }
                }
            }
            ExprKind::Eq(a, b) => self.eq_expr(a, b, e.span),
            ExprKind::IsNone(v) => {
                self.expr(v);
                self.line("ref.is_null");
            }
            ExprKind::And(a, b) => {
                self.expr(a);
                self.line("if (result i32)");
                self.expr(b);
                self.line("else");
                self.line("i32.const 0");
                self.line("end");
            }
            ExprKind::Or(a, b) => {
                self.expr(a);
                self.line("if (result i32)");
                self.line("i32.const 1");
                self.line("else");
                self.expr(b);
                self.line("end");
            }
            ExprKind::Coalesce(a, b) => {
                let inner = match &a.ty {
                    Ty::Opt(inner) => (**inner).clone(),
                    _ => Ty::Unknown,
                };
                let t = self.tmp("(ref null $Opt)");
                self.expr(a);
                self.line(&format!("local.set {t}"));
                self.line(&format!("local.get {t}"));
                self.line("ref.is_null");
                self.open_if(&e.ty);
                self.expr(b);
                self.convert(&b.ty, &e.ty);
                self.line("else");
                if self.wt(&e.ty).is_some() {
                    self.line(&format!(
                        "(struct.get $Opt 0 (ref.as_non_null (local.get {t})))"
                    ));
                    self.unslot(&inner);
                    self.convert(&inner, &e.ty);
                }
                self.line("end");
            }
            ExprKind::Range(a, b) => {
                self.expr(a);
                self.expr(b);
                self.line("call $k_range");
            }
            ExprKind::List(items) => {
                let elem = match &e.ty {
                    Ty::Adt(_, args) if !args.is_empty() => args[0].clone(),
                    _ => Ty::Unknown,
                };
                self.line(&format!("i32.const {}", items.len()));
                for item in items {
                    self.expr(item);
                    self.convert(&item.ty, &elem);
                    self.in_slot(&elem);
                }
                self.line(&format!("array.new_fixed $Slots {}", items.len()));
                self.line("struct.new $List");
            }
            ExprKind::NewMap => {
                let key = match &e.ty {
                    Ty::Adt(_, targs) if !targs.is_empty() => targs[0].clone(),
                    _ => Ty::Unknown,
                };
                let hash = self.hash_fn(&key, e.span);
                let eq = self.eq_fn(&key, e.span);
                let h = self.funcref(&hash);
                let q = self.funcref(&eq);
                self.line(&h);
                self.line(&q);
                self.line("call $k_map_new");
            }
            ExprKind::Struct { adt, fields } => {
                if fields.is_empty() {
                    self.line("ref.null $Empty");
                    return;
                }
                let decls: Vec<Ty> = match &self.p.adts[*adt].kind {
                    AdtKind::Struct(fs) => fs.iter().map(|f| f.ty.clone()).collect(),
                    AdtKind::Enum(_) => Vec::new(),
                };
                for (f, d) in fields.iter().zip(&decls) {
                    self.expr(f);
                    self.convert(&f.ty, d);
                    if self.wt(d).is_none() {
                        self.line("i32.const 0");
                    }
                }
                self.line(&format!("struct.new $S{adt}"));
            }
            ExprKind::Variant { adt, index, fields } => {
                let decls: Vec<Ty> = match &self.p.adts[*adt].kind {
                    AdtKind::Enum(vs) => vs[*index].fields.iter().map(|(_, t)| t.clone()).collect(),
                    AdtKind::Struct(_) => Vec::new(),
                };
                self.line(&format!("i32.const {index}"));
                for (f, ty) in fields.iter().zip(&decls) {
                    self.expr(f);
                    self.convert(&f.ty, ty);
                    self.in_slot(ty);
                }
                self.line(&format!("array.new_fixed $Slots {}", fields.len()));
                self.line("struct.new $Enum");
            }
            ExprKind::Field { base, field } => {
                self.expr(base);
                match &base.ty {
                    Ty::Adt(id, _) => self.line(&format!("struct.get $S{id} {field}")),
                    _ => {
                        self.line(&format!("i32.const {field}"));
                        self.line("array.get $Slots");
                    }
                }
            }
            ExprKind::Record(values) => {
                for v in values {
                    self.expr(v);
                    self.convert(&v.ty, &Ty::Any);
                }
                self.line(&format!("array.new_fixed $Slots {}", values.len()));
            }
            ExprKind::ListItem { list, index } => {
                self.expr(list);
                self.expr(index);
                self.line("call $k_list_at");
                self.unslot(&e.ty);
            }
            ExprKind::MapGet { map, key } => {
                let kt = match &map.ty {
                    Ty::Adt(_, args) if !args.is_empty() => args[0].clone(),
                    _ => Ty::Unknown,
                };
                self.expr(map);
                self.expr(key);
                self.convert(&key.ty, &kt);
                self.in_slot(&kt);
                self.line("call $k_map_get");
            }
            ExprKind::Call { func, args } => {
                if self.p.funcs[*func].server && self.browser {
                    self.server_call(*func, e.span);
                    return;
                }
                let params: Vec<Ty> = self.p.funcs[*func]
                    .params
                    .iter()
                    .map(|&l| self.p.funcs[*func].locals[l].ty.clone())
                    .collect();
                for (a, pt) in args.iter().zip(&params) {
                    self.expr(a);
                    self.convert(&a.ty, pt);
                }
                self.line(&format!("call $f{func}"));
                let ret = self.p.funcs[*func].ret.clone();
                if self.wt(&ret).is_some() {
                    self.convert(&ret, &e.ty);
                }
            }
            ExprKind::CallClosure { callee, args } => {
                let Ty::Fn(f) = &callee.ty else {
                    return self.unsupported(e.span, "this call");
                };
                let f = f.clone();
                let c = self.tmp("(ref null $Closure)");
                self.expr(callee);
                self.line(&format!("local.set {c}"));
                self.line(&format!("(struct.get $Closure 1 (local.get {c}))"));
                for (a, ty) in args.iter().zip(&f.params) {
                    self.expr(a);
                    self.convert(&a.ty, ty);
                    self.in_slot(ty);
                }
                self.line(&format!("array.new_fixed $Slots {}", args.len()));
                self.line(&format!("(struct.get $Closure 0 (local.get {c}))"));
                self.line("call_ref $Code");
                if self.wt(&f.ret).is_some() {
                    self.unslot(&f.ret);
                    self.convert(&f.ret, &e.ty);
                } else {
                    self.line("drop");
                }
            }
            ExprKind::Method { name, recv, args } => {
                self.expr(recv);
                for a in args {
                    self.expr(a);
                }
                self.builtin_method(&recv.ty, name, args, &e.ty, e.span);
            }
            ExprKind::Lib { module, name, args } => {
                self.lib_call(module, name, args, &e.ty, e.span);
            }
            ExprKind::Print(v) => {
                self.expr(v);
                self.line("call $k_print");
            }
            ExprKind::Env(_) => self.server_only(e.span, "`env`"),
            ExprKind::Panic(v) => {
                self.expr(v);
                self.line("call $k_panic");
            }
            ExprKind::Log { level, args } => {
                let c = self.str_const(level);
                self.line(&c);
                let mut parts = args.iter();
                if let Some(m) = parts.next() {
                    self.expr(m);
                }
                self.line("global.get $s_empty");
                for (i, a) in parts.enumerate() {
                    if i > 0 {
                        let sp = self.str_const(" ");
                        self.line(&sp);
                        self.line("call $k_concat");
                    }
                    self.expr(a);
                    self.line("call $k_concat");
                }
                self.line("call $k_log");
            }
            ExprKind::Closure { func, captures } => {
                let r = self.funcref(&format!("$f{func}"));
                self.line(&r);
                if captures.is_empty() {
                    self.line("ref.null $Slots");
                } else {
                    for &l in captures {
                        let lw = self.f.locals[l].clone();
                        if lw.cell.is_some() {
                            self.line(&format!("local.get {}", lw.name));
                        } else {
                            let ty = self.f.tys[l].clone();
                            self.get_local(l);
                            self.in_slot(&ty);
                        }
                    }
                    self.line(&format!("array.new_fixed $Slots {}", captures.len()));
                }
                self.line("struct.new $Closure");
            }
            ExprKind::If {
                cond,
                then,
                otherwise,
            } => {
                self.expr(cond);
                self.open_if(&e.ty);
                let want = self.wt(&e.ty).is_some();
                self.branch(then, &e.ty, want);
                if let Some(o) = otherwise {
                    self.line("else");
                    self.branch(o, &e.ty, want);
                } else if want {
                    self.line("else");
                    self.line("unreachable");
                }
                self.line("end");
            }
            ExprKind::Match { scrutinee, arms } => self.match_expr(e, scrutinee, arms),
            ExprKind::Is { value, pattern } => {
                let vt = value.ty.clone();
                let s = self.tmp_ty(&vt);
                self.expr(value);
                if let Some(s) = &s {
                    self.line(&format!("local.set {s}"));
                }
                let done = self.label("is");
                let fail = self.label("isnot");
                self.line(&format!("block {done} (result i32)"));
                self.line(&format!("block {fail}"));
                self.pattern(pattern, s.as_deref(), &vt, &fail);
                self.line("i32.const 1");
                self.line(&format!("br {done}"));
                self.line("end");
                self.line("i32.const 0");
                self.line("end");
            }
            ExprKind::Block(b) => {
                let want = self.wt(&e.ty).is_some();
                self.block(b, want);
                if want {
                    let bt = block_ty(b);
                    if self.wt(&bt).is_some() {
                        self.convert(&bt, &e.ty);
                    } else {
                        self.line("unreachable");
                    }
                }
            }
            ExprKind::Try { expr, wrap } => {
                self.expr(expr);
                self.convert(&expr.ty, &e.ty);
                self.line("global.get $failed");
                self.line("if");
                if *wrap {
                    self.wrap_error();
                }
                self.fail_return();
                self.line("end");
            }
            ExprKind::Catch {
                expr,
                err,
                binding,
                handler,
            } => {
                let r = self.tmp_ty(&e.ty);
                self.expr(expr);
                match &r {
                    Some(r) if self.wt(&expr.ty).is_some() => {
                        self.convert(&expr.ty, &e.ty);
                        self.line(&format!("local.set {r}"));
                    }
                    _ => {
                        if self.wt(&expr.ty).is_some() {
                            self.line("drop");
                        }
                    }
                }
                self.line("global.get $failed");
                self.line("if");
                self.line("call $k_take_error");
                match binding {
                    Some(b) => {
                        self.unslot(err);
                        let bt = self.f.tys[*b].clone();
                        self.convert(err, &bt);
                        self.init_local(*b);
                    }
                    None => self.line("drop"),
                }
                let ht = block_ty(handler);
                self.block(handler, r.is_some());
                if let Some(r) = &r {
                    if self.wt(&ht).is_some() {
                        self.convert(&ht, &e.ty);
                        self.line(&format!("local.set {r}"));
                    }
                }
                self.line("end");
                if let Some(r) = &r {
                    self.line(&format!("local.get {r}"));
                }
            }
            ExprKind::Throw { value, wrap } => self.throw(value, *wrap),
            ExprKind::Coerce(v) => {
                self.expr(v);
                self.convert(&v.ty, &e.ty);
            }
            ExprKind::Error => self.line("unreachable"),
        }
    }

    fn open_if(&mut self, ty: &Ty) {
        match self.wt(ty) {
            Some(wt) => self.line(&format!("if (result {wt})")),
            None => self.line("if"),
        }
    }

    fn branch(&mut self, b: &Block, rt: &Ty, want: bool) {
        self.block(b, want);
        if want {
            let bt = block_ty(b);
            if self.wt(&bt).is_some() {
                self.convert(&bt, rt);
            } else {
                self.line("unreachable");
            }
        }
    }

    /// A top-level function used as a value, wrapped as a closure.
    fn fn_value(&mut self, id: FuncId) {
        let wrapper = format!("$w{id}");
        if let std::collections::hash_map::Entry::Vacant(e) =
            self.helper_names.entry(format!("fn:{id}"))
        {
            e.insert(wrapper.clone());
            let func = &self.p.funcs[id];
            let mut b = format!("  (func {wrapper} (type $Code)\n");
            for (i, &p) in func.params.iter().enumerate() {
                let _ = writeln!(b, "    (array.get $Slots (local.get 1) (i32.const {i}))");
                b.push_str(&self.unslot_text(&func.locals[p].ty));
            }
            let _ = writeln!(b, "    call $f{id}");
            if self.wt(&func.ret).is_some() {
                b.push_str(&self.slot_text(&func.ret));
            } else {
                b.push_str("    ref.null any\n");
            }
            b.push_str("  )\n");
            self.helpers.push_str(&b);
        }
        let r = self.funcref(&wrapper);
        self.line(&r);
        self.line("ref.null $Slots");
        self.line("struct.new $Closure");
    }

    fn slot_text(&mut self, ty: &Ty) -> String {
        let saved = std::mem::take(&mut self.f.body);
        self.in_slot(ty);
        std::mem::replace(&mut self.f.body, saved)
    }

    fn unslot_text(&mut self, ty: &Ty) -> String {
        let saved = std::mem::take(&mut self.f.body);
        self.unslot(ty);
        std::mem::replace(&mut self.f.body, saved)
    }

    fn match_expr(&mut self, e: &Expr, scrutinee: &Expr, arms: &[Arm]) {
        let st = scrutinee.ty.clone();
        let s = self.tmp_ty(&st);
        self.expr(scrutinee);
        if let Some(s) = &s {
            self.line(&format!("local.set {s}"));
        }
        let done = self.label("match");
        match self.wt(&e.ty) {
            Some(wt) => self.line(&format!("block {done} (result {wt})")),
            None => self.line(&format!("block {done}")),
        }
        let want = self.wt(&e.ty).is_some();
        for arm in arms {
            let next = self.label("arm");
            self.line(&format!("block {next}"));
            self.pattern(&arm.pattern, s.as_deref(), &st, &next);
            if let Some(guard) = &arm.guard {
                self.expr(guard);
                self.line("i32.eqz");
                self.line(&format!("br_if {next}"));
            }
            self.expr(&arm.body);
            if want {
                if self.wt(&arm.body.ty).is_some() {
                    self.convert(&arm.body.ty, &e.ty);
                } else {
                    self.line("unreachable");
                }
            } else if self.wt(&arm.body.ty).is_some() {
                self.line("drop");
            }
            self.line(&format!("br {done}"));
            self.line("end");
        }
        let c = self.str_const("no arm of this match matched");
        self.line(&c);
        self.line("call $k_panic");
        self.line("unreachable");
        self.line("end");
    }

    /// Checks that the value in local `val` (of type `ty`) matches `p`,
    /// branching to `fail` when it does not, and binds its names.
    fn pattern(&mut self, p: &Pattern, val: Option<&str>, ty: &Ty, fail: &str) {
        let get = |g: &mut Self| {
            if let Some(v) = val {
                g.line(&format!("local.get {v}"));
            }
        };
        match p {
            Pattern::Wildcard => {}
            Pattern::Bind(l) => {
                get(self);
                let lt = self.f.tys[*l].clone();
                if val.is_some() {
                    self.convert(ty, &lt);
                    self.init_local(*l);
                }
            }
            Pattern::Literal(lit) => {
                get(self);
                self.expr(lit);
                self.eq_on_stack(ty, &lit.ty, lit.span);
                self.line("i32.eqz");
                self.line(&format!("br_if {fail}"));
            }
            Pattern::None => {
                get(self);
                self.line("ref.is_null");
                self.line("i32.eqz");
                self.line(&format!("br_if {fail}"));
            }
            Pattern::Some(inner, ity) => {
                get(self);
                self.line("ref.is_null");
                self.line(&format!("br_if {fail}"));
                let t = self.tmp_ty(ity);
                get(self);
                self.line("ref.as_non_null");
                self.line("struct.get $Opt 0");
                self.unslot(ity);
                if let Some(t) = &t {
                    self.line(&format!("local.set {t}"));
                }
                self.pattern(inner, t.as_deref(), ity, fail);
            }
            Pattern::Variant { index, fields, .. } => {
                get(self);
                self.line("struct.get $Enum 0");
                self.line(&format!("i32.const {index}"));
                self.line("i32.ne");
                self.line(&format!("br_if {fail}"));
                for (j, (sub, fty)) in fields.iter().enumerate() {
                    if matches!(sub, Pattern::Wildcard) {
                        continue;
                    }
                    let t = self.tmp_ty(fty);
                    get(self);
                    self.line("struct.get $Enum 1");
                    self.line(&format!("i32.const {j}"));
                    self.line("array.get $Slots");
                    self.unslot(fty);
                    if let Some(t) = &t {
                        self.line(&format!("local.set {t}"));
                    }
                    self.pattern(sub, t.as_deref(), fty, fail);
                }
            }
        }
    }

    // ----- errors -----

    /// Wraps the current error in the standard `Error`, with the error's
    /// text as its message.
    fn wrap_error(&mut self) {
        self.line("global.get $error");
        self.line("global.get $error_show");
        self.line("call_ref $ShowF");
        let id = self.prims.error;
        self.line(&format!("struct.new $S{id}"));
        self.line("global.set $error");
        let show = self.error_message_fn();
        let r = self.funcref(&show);
        self.line(&r);
        self.line("global.set $error_show");
    }

    fn throw(&mut self, value: &Expr, wrap: bool) {
        let mut et = value.ty.clone();
        self.expr(value);
        if wrap {
            self.display(&et, value.span);
            let id = self.prims.error;
            self.line(&format!("struct.new $S{id}"));
            et = Ty::Adt(self.prims.error, Vec::new());
        }
        let show = if self.is_adt(&et, self.prims.error) {
            self.error_message_fn()
        } else {
            self.show_fn(&et, false, value.span)
        };
        self.in_slot(&et);
        let r = self.funcref(&show);
        self.line(&r);
        self.line("call $k_fail");
        self.fail_return();
    }

    /// After a library call that may have failed, turns its message into
    /// a failed standard `Error`.
    fn lib_failed(&mut self) {
        let id = self.prims.error;
        let show = self.error_message_fn();
        let r = self.funcref(&show);
        self.line("global.get $lib_error");
        self.line("ref.is_null");
        self.line("i32.eqz");
        self.line("if");
        self.line("global.get $lib_error");
        self.line(&format!("struct.new $S{id}"));
        self.line(&r);
        self.line("call $k_fail");
        self.line("ref.null extern");
        self.line("global.set $lib_error");
        self.line("end");
    }

    fn error_message_fn(&mut self) -> String {
        let name = "$k_error_message".to_string();
        if !self.helper_names.contains_key("error-message") {
            self.helper_names
                .insert("error-message".into(), name.clone());
            let id = self.prims.error;
            let _ = write!(
                self.helpers,
                "  (func {name} (type $ShowF)\n    (struct.get $S{id} 0 (ref.cast (ref $S{id}) (local.get 0))))\n"
            );
        }
        name
    }

    /// A call to a `server fn` that is not one the ember's handler code
    /// turned into a request.
    fn server_call(&mut self, func: FuncId, span: Span) {
        let name = self.p.funcs[func].name.clone();
        self.diags.push(
            Diagnostic::error(
                codes::SERVER_CALL_PLACE,
                format!("`{name}` runs on the server, so the browser can call it only from an `on:` handler, as a statement of its own"),
                span,
            )
            .with_help(format!(
                "write the call in the handler: `on:click={{ result = {name}(...) }}`"
            )),
        );
        self.line("unreachable");
    }

    // ----- standard library methods -----

    fn builtin_method(&mut self, recv: &Ty, name: &str, args: &[Expr], rt: &Ty, span: Span) {
        let Ty::Adt(id, targs) = recv else {
            return self.unsupported(span, format!("`.{name}`"));
        };
        let id = *id;
        let p = self.prims;
        let call = |g: &mut Self, f: &str| g.line(&format!("call {f}"));
        if id == p.int {
            return match name {
                "to_string" => call(self, "$k_int_str"),
                "to_float" => self.line("f64.convert_i64_s"),
                "abs" | "min" | "max" | "pow" | "clamp" => call(self, &format!("$k_{name}")),
                _ => self.unsupported(span, format!("`Int.{name}`")),
            };
        }
        if id == p.duration {
            return match name {
                "to_millis" => {
                    self.line("i64.const 1000000");
                    self.line("i64.div_s");
                }
                "to_seconds" => {
                    self.line("f64.convert_i64_s");
                    self.line("f64.const 1e9");
                    self.line("f64.div");
                }
                _ => self.unsupported(span, format!("`Duration.{name}`")),
            };
        }
        if id == p.float {
            return match name {
                "to_string" => call(self, "$k_float_str"),
                "round" => {
                    call(self, "$k_round");
                    call(self, "$k_float_to_int");
                }
                "floor" | "ceil" => {
                    self.line(&format!("f64.{name}"));
                    call(self, "$k_float_to_int");
                }
                "abs" | "sqrt" => self.line(&format!("f64.{name}")),
                "min" => call(self, "$k_fmin"),
                "max" => call(self, "$k_fmax"),
                "fixed" => call(self, "$k_float_fixed"),
                _ => self.unsupported(span, format!("`Float.{name}`")),
            };
        }
        if id == p.string {
            return match name {
                "len" => call(self, "$k_str_len"),
                "is_empty" => call(self, "$k_str_empty"),
                "upper" | "lower" | "trim" | "trim_start" | "trim_end" | "contains"
                | "starts_with" | "ends_with" | "replace" | "slice" | "repeat" => {
                    call(self, &format!("$k_str_{name}"))
                }
                "to_int" => call(self, "$k_str_to_int_opt"),
                "to_float" => call(self, "$k_str_to_float_opt"),
                "index_of" => call(self, "$k_str_index_of_opt"),
                "split" => {
                    call(self, "$k_str_split_js");
                    call(self, "$k_list_of_js");
                }
                "chars" | "lines" => {
                    call(self, &format!("$k_str_{name}_js"));
                    call(self, "$k_list_of_js");
                }
                "pad_start" | "pad_end" => {
                    self.line(&format!("i32.const {}", i32::from(name == "pad_start")));
                    call(self, "$k_str_pad");
                }
                _ => self.unsupported(span, format!("`String.{name}`")),
            };
        }
        if id == p.list {
            let elem = targs.first().cloned().unwrap_or(Ty::Unknown);
            return match name {
                "len" => {
                    call(self, "$k_len");
                    self.line("i64.extend_i32_s");
                }
                "is_empty" => {
                    call(self, "$k_len");
                    self.line("i32.eqz");
                }
                "first" | "last" | "reverse" | "pop" | "get" | "push" | "filter" | "map"
                | "find" | "any" | "all" | "remove_at" | "take" | "skip" | "concat" | "count"
                | "flat_map" | "insert" | "slice" | "fold" => {
                    call(self, &format!("$k_list_{name}"));
                    let _ = rt;
                }
                "contains" | "index_of" => {
                    let eq = self.eq_fn(&elem, span);
                    let r = self.funcref(&eq);
                    self.line(&r);
                    call(self, &format!("$k_list_{name}"));
                }
                "sort" => {
                    let cmp = self.cmp_fn(&elem, span);
                    let r = self.funcref(&cmp);
                    self.line(&r);
                    call(self, "$k_list_sort");
                }
                "min" | "max" => {
                    let cmp = self.cmp_fn(&elem, span);
                    let r = self.funcref(&cmp);
                    self.line(&r);
                    self.line(&format!("i32.const {}", if name == "min" { 1 } else { -1 }));
                    call(self, "$k_list_extreme");
                }
                "sort_by" => {
                    let key = match args.first().map(|a| &a.uncoerced().ty) {
                        Some(Ty::Fn(f)) => f.ret.clone(),
                        _ => Ty::Unknown,
                    };
                    let cmp = self.cmp_fn(&key, span);
                    let r = self.funcref(&cmp);
                    self.line(&r);
                    call(self, "$k_list_sort_by");
                }
                "join" => {
                    let show = self.show_fn(&elem, false, span);
                    let r = self.funcref(&show);
                    self.line(&r);
                    call(self, "$k_list_join");
                }
                _ => self.unsupported(span, format!("`List.{name}`")),
            };
        }
        if id == p.map || id == p.set {
            let set = id == p.set;
            return match name {
                "len" => {
                    self.line("struct.get $Map 0");
                    self.line("i64.extend_i32_s");
                }
                "is_empty" => {
                    self.line("struct.get $Map 0");
                    self.line("i32.eqz");
                }
                "keys" | "to_list" => {
                    self.line("i32.const 0");
                    call(self, "$k_map_list");
                }
                "values" => {
                    self.line("i32.const 1");
                    call(self, "$k_map_list");
                }
                "entries" => {
                    self.line("i32.const 2");
                    call(self, "$k_map_list");
                }
                "get" | "contains" => call(self, &format!("$k_map_{name}")),
                "remove" if set => call(self, "$k_set_remove"),
                "remove" => call(self, "$k_map_remove"),
                "add" => call(self, "$k_set_add"),
                "set" => call(self, "$k_map_set"),
                _ => self.unsupported(span, format!("`{}.{name}`", self.p.adts[id].name)),
            };
        }
        let what = format!("`{}.{name}`", self.p.adts[id].name);
        self.unsupported(span, what)
    }

    // ----- standard library modules -----

    fn lib_call(&mut self, module: &str, name: &str, args: &[Expr], ty: &Ty, span: Span) {
        match (module, name) {
            // `stores.scope`: the stores' values are saved on a stack, and
            // the stores start again until they are put back.
            ("stores", "enter") => {
                let n = self.p.stores.len();
                self.line("global.get $st_saved");
                for i in 0..n {
                    self.line(&format!("global.get $st{i}"));
                }
                self.line(&format!("array.new_fixed $StArr {n}"));
                self.line("struct.new $StSave");
                self.line("global.set $st_saved");
                for i in 0..n {
                    self.line("ref.null $Opt");
                    self.line(&format!("global.set $st{i}"));
                }
            }
            ("stores", "leave") => {
                for i in 0..self.p.stores.len() {
                    self.line("global.get $st_saved");
                    self.line("struct.get $StSave 1");
                    self.line(&format!("i32.const {i}"));
                    self.line("array.get $StArr");
                    self.line(&format!("global.set $st{i}"));
                }
                self.line("global.get $st_saved");
                self.line("struct.get $StSave 0");
                self.line("global.set $st_saved");
            }
            ("html", "escape") | ("html", "safe_url") | ("ui", "merge") | ("base64", "encode") => {
                for a in args {
                    self.expr(a);
                }
                let f = match name {
                    "escape" => "$k_html_escape",
                    "safe_url" => "$k_safe_url",
                    "merge" => "$k_ui_merge",
                    _ => "$k_base64_encode",
                };
                self.line(&format!("call {f}"));
            }
            ("base64", "decode") => {
                for a in args {
                    self.expr(a);
                }
                self.line("call $k_base64_decode");
                self.line("call $k_take_error_js");
                self.line("global.set $lib_error");
                self.lib_failed();
            }
            ("json", "encode") => {
                let Some(a) = args.first() else { return };
                let value = a.described_expr();
                let vt = value.ty.clone();
                self.expr(value);
                self.in_slot(&vt);
                let f = json::encode_fn(self, &vt, span);
                self.line(&format!("call {f}"));
            }
            ("json", "decode") => {
                let Some(a) = args.first() else { return };
                self.expr(a);
                json::decode(self, ty, span);
                let Some(wt) = self.wt(ty) else {
                    self.line("drop");
                    return self.lib_failed();
                };
                let t = self.tmp("anyref");
                self.line(&format!("local.set {t}"));
                self.line("global.get $lib_error");
                self.line("ref.is_null");
                self.line(&format!("if (result {wt})"));
                self.line(&format!("local.get {t}"));
                self.unslot(ty);
                self.line("else");
                self.line(&default_value(&wt));
                self.line("end");
                self.lib_failed();
            }
            ("ember" | "browser" | "js", _) => {
                browser::lib_call(self, module, name, args, ty, span)
            }
            ("fs" | "os" | "io" | "web" | "sql" | "auth", _) => {
                for a in args {
                    self.discard(a);
                }
                self.server_only(span, &format!("`{module}.{name}`"));
            }
            _ => {
                for a in args {
                    self.discard(a);
                }
                // `Bytes` methods are the prelude's, written without a module.
                let what = match module {
                    "prelude" => format!("`{name}`"),
                    _ => format!("`{module}.{name}`"),
                };
                self.unsupported(span, what);
            }
        }
    }

    // ----- showing, comparing and ordering values -----

    /// Turns the value on the stack into the `String` `print` shows.
    fn display(&mut self, ty: &Ty, span: Span) {
        let p = self.prims;
        match ty {
            _ if self.is_string(ty) => {}
            Ty::Adt(id, _) if *id == p.int => self.line("call $k_int_str"),
            Ty::Adt(id, _) if *id == p.float => self.line("call $k_float_str"),
            Ty::Adt(id, _) if *id == p.bool_ => self.line("call $k_bool_str"),
            Ty::Adt(id, _) if *id == p.duration => self.line("call $k_duration_str"),
            _ => {
                let f = self.show_fn(ty, false, span);
                self.in_slot(ty);
                self.line(&format!("call {f}"));
            }
        }
    }

    fn helper(&mut self, key: String, prefix: &str) -> (String, bool) {
        if let Some(name) = self.helper_names.get(&key) {
            return (name.clone(), false);
        }
        let name = format!("${prefix}{}", self.next());
        self.helper_names.insert(key, name.clone());
        (name, true)
    }

    /// Runs `f` with an empty function state, for writing a helper
    /// function's body, and returns the body and its locals.
    pub(crate) fn in_helper(&mut self, f: impl FnOnce(&mut Self)) -> String {
        let saved = std::mem::take(&mut self.f);
        f(self);
        let st = std::mem::replace(&mut self.f, saved);
        format!("{}{}", st.decls, st.body)
    }

    pub(crate) fn emit_helper(&mut self, header: &str, body: String) {
        let _ = write!(self.helpers, "  {header}\n{body}  )\n");
    }

    /// A `$ShowF` function that shows values of `ty`. Strings are quoted
    /// when `quote` is set, as they are inside lists and structs.
    fn show_fn(&mut self, ty: &Ty, quote: bool, span: Span) -> String {
        let (name, fresh) = self.helper(format!("show:{quote}:{ty:?}"), "show");
        if !fresh {
            return name;
        }
        let p = self.prims;
        let body = self.in_helper(|g| match ty {
            _ if g.is_string(ty) => {
                g.line("local.get 0");
                g.line("extern.convert_any");
                if quote {
                    g.line("call $k_str_quote");
                }
            }
            Ty::Adt(id, _) if g.wt(ty).as_deref() == Some("i64") || *id == p.float || *id == p.bool_ => {
                g.line("local.get 0");
                g.unslot(ty);
                g.display(ty, span);
            }
            Ty::Opt(inner) => {
                let f = g.show_fn(inner, quote, span);
                let none = g.str_const("none");
                g.line("local.get 0");
                g.line("ref.is_null");
                g.line("if (result externref)");
                g.line(&none);
                g.line("else");
                g.line("(struct.get $Opt 0 (ref.cast (ref $Opt) (local.get 0)))");
                g.line(&format!("call {f}"));
                g.line("end");
            }
            Ty::Fn(_) => {
                let c = g.str_const("<fn>");
                g.line(&c);
            }
            Ty::Adt(id, args) if *id == p.list => {
                let f = g.show_fn(&args[0], true, span);
                let r = g.funcref(&f);
                g.line("(ref.cast (ref null $List) (local.get 0))");
                g.line(&r);
                g.line("call $k_list_show");
            }
            Ty::Adt(id, args) if *id == p.map || *id == p.set => {
                let k = g.show_fn(&args[0], true, span);
                let kr = g.funcref(&k);
                g.line("(ref.cast (ref null $Map) (local.get 0))");
                g.line(&kr);
                if *id == p.map {
                    let v = g.show_fn(&args[1], true, span);
                    let vr = g.funcref(&v);
                    g.line(&vr);
                } else {
                    g.line("ref.null $ShowF");
                }
                g.line("call $k_map_show");
            }
            Ty::Adt(id, args) if !g.p.is_prim(*id) => {
                let adt = g.p.adts[*id].clone();
                let map = g.type_map(*id, args);
                match &adt.kind {
                    AdtKind::Struct(fields) if fields.is_empty() => {
                        let c = g.str_const(&adt.name);
                        g.line(&c);
                    }
                    AdtKind::Struct(fields) => {
                        let x = g.tmp(&format!("(ref null $S{id})"));
                        g.line(&format!("(local.set {x} (ref.cast (ref null $S{id}) (local.get 0)))"));
                        let c = g.str_const(&format!("{}(", adt.name));
                        g.line(&c);
                        for (i, f) in fields.iter().enumerate() {
                            let fty = substitute(&f.ty, &map);
                            let show = g.show_fn(&fty, true, span);
                            let label = if i == 0 {
                                format!("{}: ", f.name)
                            } else {
                                format!(", {}: ", f.name)
                            };
                            let l = g.str_const(&label);
                            g.line(&l);
                            g.line("call $k_concat");
                            g.line(&format!("(struct.get $S{id} {i} (local.get {x}))"));
                            g.in_slot(&f.ty);
                            g.line(&format!("call {show}"));
                            g.line("call $k_concat");
                        }
                        let c = g.str_const(")");
                        g.line(&c);
                        g.line("call $k_concat");
                    }
                    AdtKind::Enum(variants) => {
                        let x = g.tmp("(ref null $Enum)");
                        g.line(&format!("(local.set {x} (ref.cast (ref null $Enum) (local.get 0)))"));
                        for (i, var) in variants.iter().enumerate() {
                            g.line(&format!("(struct.get $Enum 0 (local.get {x}))"));
                            g.line(&format!("i32.const {i}"));
                            g.line("i32.eq");
                            g.line("if");
                            if var.fields.is_empty() {
                                let c = g.str_const(&var.name);
                                g.line(&c);
                            } else {
                                let c = g.str_const(&format!("{}(", var.name));
                                g.line(&c);
                                for (j, (fname, fty)) in var.fields.iter().enumerate() {
                                    let fty = substitute(fty, &map);
                                    let show = g.show_fn(&fty, true, span);
                                    let sep = if j == 0 { "" } else { ", " };
                                    let label = match fname {
                                        Some(n) => format!("{sep}{n}: "),
                                        None => sep.to_string(),
                                    };
                                    if !label.is_empty() {
                                        let l = g.str_const(&label);
                                        g.line(&l);
                                        g.line("call $k_concat");
                                    }
                                    g.line(&format!("(array.get $Slots (struct.get $Enum 1 (local.get {x})) (i32.const {j}))"));
                                    g.line(&format!("call {show}"));
                                    g.line("call $k_concat");
                                }
                                let c = g.str_const(")");
                                g.line(&c);
                                g.line("call $k_concat");
                            }
                            g.line("return");
                            g.line("end");
                        }
                        let c = g.str_const("?");
                        g.line(&c);
                    }
                }
            }
            Ty::Record(fields) => {
                let x = g.tmp("(ref null $Slots)");
                g.line(&format!("(local.set {x} (ref.cast (ref null $Slots) (local.get 0)))"));
                let c = g.str_const("{ ");
                g.line(&c);
                for (i, (fname, fty)) in fields.iter().enumerate() {
                    let show = g.show_fn(fty, true, span);
                    let sep = if i == 0 { "" } else { ", " };
                    let l = g.str_const(&format!("{sep}{fname}: "));
                    g.line(&l);
                    g.line("call $k_concat");
                    g.line(&format!("(array.get $Slots (local.get {x}) (i32.const {i}))"));
                    g.line(&format!("call {show}"));
                    g.line("call $k_concat");
                }
                let c = g.str_const(" }");
                g.line(&c);
                g.line("call $k_concat");
            }
            Ty::Param(_) | Ty::Var(_) | Ty::Any => {
                g.diags.push(Diagnostic::error(
                    codes::NOT_COMPILED_YET,
                    "showing a value whose type is a generic parameter is not supported by the compiler yet",
                    span,
                ));
                g.line("global.get $s_empty");
            }
            _ => {
                let what = g.not_compiled(ty, "showing a value of this type");
                g.diags.push(Diagnostic::error(codes::NOT_COMPILED_YET, what, span));
                g.line("global.get $s_empty");
            }
        });
        self.emit_helper(&format!("(func {name} (type $ShowF)"), body);
        name
    }

    /// Whether two values are equal: pushes them and compares them.
    fn eq_expr(&mut self, a: &Expr, b: &Expr, span: Span) {
        let (at, bt) = (a.ty.clone(), b.ty.clone());
        let ty = match (&at, &bt) {
            (Ty::Opt(_), other) if !matches!(other, Ty::Opt(_)) => {
                self.expr(a);
                self.expr(b);
                self.convert(&bt, &at);
                at.clone()
            }
            (other, Ty::Opt(_)) if !matches!(other, Ty::Opt(_)) => {
                self.expr(a);
                self.convert(&at, &bt);
                self.expr(b);
                bt.clone()
            }
            _ => {
                self.expr(a);
                self.expr(b);
                if self.is_slot(&bt) && !self.is_slot(&at) {
                    self.unslot(&at);
                }
                at.clone()
            }
        };
        self.compare_eq(&ty, span);
    }

    /// The value pushed before (of type `at`) and a value of type `bt`
    /// pushed after it, compared.
    fn eq_on_stack(&mut self, at: &Ty, bt: &Ty, span: Span) {
        if matches!(at, Ty::Opt(_)) && !matches!(bt, Ty::Opt(_)) {
            self.convert(bt, at);
        }
        self.compare_eq(at, span);
    }

    fn compare_eq(&mut self, ty: &Ty, span: Span) {
        if self.is_string(ty) {
            self.line("call $k_str_eq");
            return;
        }
        match self.wt(ty).as_deref() {
            Some("i64") => self.line("i64.eq"),
            Some("f64") => self.line("f64.eq"),
            Some("i32") => self.line("i32.eq"),
            None => self.line("i32.const 1"),
            _ => {
                let f = self.eq_fn(ty, span);
                self.line(&format!("call {f}"));
            }
        }
    }

    /// An `$EqF` function that compares values of `ty`, as slots.
    pub(crate) fn eq_fn(&mut self, ty: &Ty, span: Span) -> String {
        let (name, fresh) = self.helper(format!("eq:{ty:?}"), "eq");
        if !fresh {
            return name;
        }
        let p = self.prims;
        let body = self.in_helper(|g| match ty {
            _ if g.is_string(ty) => {
                g.line("(extern.convert_any (local.get 0))");
                g.line("(extern.convert_any (local.get 1))");
                g.line("call $k_str_eq");
            }
            Ty::Adt(..) if matches!(g.wt(ty).as_deref(), Some("i64" | "f64" | "i32")) => {
                g.line("local.get 0");
                g.unslot(ty);
                g.line("local.get 1");
                g.unslot(ty);
                g.compare_eq(ty, span);
            }
            Ty::Fn(_) => {
                g.line("local.get 0");
                g.line("local.get 1");
                g.line("call $k_eq_ref");
            }
            Ty::Opt(inner) => {
                let f = g.eq_fn(inner, span);
                g.line("(i32.or (ref.is_null (local.get 0)) (ref.is_null (local.get 1)))");
                g.line("if (result i32)");
                g.line("(i32.and (ref.is_null (local.get 0)) (ref.is_null (local.get 1)))");
                g.line("else");
                g.line("(struct.get $Opt 0 (ref.cast (ref $Opt) (local.get 0)))");
                g.line("(struct.get $Opt 0 (ref.cast (ref $Opt) (local.get 1)))");
                g.line(&format!("call {f}"));
                g.line("end");
            }
            Ty::Adt(id, args) if *id == p.map || *id == p.set => {
                g.line("(ref.cast (ref null $Map) (local.get 0))");
                g.line("(ref.cast (ref null $Map) (local.get 1))");
                if *id == p.map {
                    let f = g.eq_fn(&args[1], span);
                    let r = g.funcref(&f);
                    g.line(&r);
                } else {
                    g.line("ref.null $EqF");
                }
                g.line("call $k_map_eq");
            }
            Ty::Adt(id, args) if *id == p.list => {
                let f = g.eq_fn(&args[0], span);
                let (x, y, i) = (
                    g.tmp("(ref null $List)"),
                    g.tmp("(ref null $List)"),
                    g.tmp("i32"),
                );
                g.line(&format!("(local.set {x} (ref.cast (ref null $List) (local.get 0)))"));
                g.line(&format!("(local.set {y} (ref.cast (ref null $List) (local.get 1)))"));
                g.line(&format!("(if (i32.ne (call $k_len (local.get {x})) (call $k_len (local.get {y}))) (then (return (i32.const 0))))"));
                g.line(&format!("(block $done (loop $next (br_if $done (i32.ge_s (local.get {i}) (call $k_len (local.get {x})))) (if (i32.eqz (call {f} (call $k_item (local.get {x}) (local.get {i})) (call $k_item (local.get {y}) (local.get {i})))) (then (return (i32.const 0)))) (local.set {i} (i32.add (local.get {i}) (i32.const 1))) (br $next)))"));
                g.line("i32.const 1");
            }
            Ty::Adt(id, args) if !g.p.is_prim(*id) => {
                let adt = g.p.adts[*id].clone();
                let map = g.type_map(*id, args);
                match &adt.kind {
                    AdtKind::Struct(fields) if fields.is_empty() => g.line("i32.const 1"),
                    AdtKind::Struct(fields) => {
                        let s = format!("(ref null $S{id})");
                        let (x, y) = (g.tmp(&s), g.tmp(&s));
                        g.line(&format!("(local.set {x} (ref.cast {s} (local.get 0)))"));
                        g.line(&format!("(local.set {y} (ref.cast {s} (local.get 1)))"));
                        for (i, f) in fields.iter().enumerate() {
                            let fty = substitute(&f.ty, &map);
                            let eq = g.eq_fn(&fty, span);
                            g.line(&format!("(struct.get $S{id} {i} (local.get {x}))"));
                            g.in_slot(&f.ty);
                            g.line(&format!("(struct.get $S{id} {i} (local.get {y}))"));
                            g.in_slot(&f.ty);
                            g.line(&format!("call {eq}"));
                            g.line("i32.eqz");
                            g.line("(if (then (return (i32.const 0))))");
                        }
                        g.line("i32.const 1");
                    }
                    AdtKind::Enum(variants) => {
                        let (x, y) = (g.tmp("(ref null $Enum)"), g.tmp("(ref null $Enum)"));
                        g.line(&format!("(local.set {x} (ref.cast (ref null $Enum) (local.get 0)))"));
                        g.line(&format!("(local.set {y} (ref.cast (ref null $Enum) (local.get 1)))"));
                        g.line(&format!("(if (i32.ne (struct.get $Enum 0 (local.get {x})) (struct.get $Enum 0 (local.get {y}))) (then (return (i32.const 0))))"));
                        for (i, var) in variants.iter().enumerate() {
                            if var.fields.is_empty() {
                                continue;
                            }
                            g.line(&format!("(if (i32.eq (struct.get $Enum 0 (local.get {x})) (i32.const {i})) (then"));
                            for (j, (_, fty)) in var.fields.iter().enumerate() {
                                let fty = substitute(fty, &map);
                                let eq = g.eq_fn(&fty, span);
                                g.line(&format!("(if (i32.eqz (call {eq} (array.get $Slots (struct.get $Enum 1 (local.get {x})) (i32.const {j})) (array.get $Slots (struct.get $Enum 1 (local.get {y})) (i32.const {j})))) (then (return (i32.const 0))))"));
                            }
                            g.line("))");
                        }
                        g.line("i32.const 1");
                    }
                }
            }
            Ty::Record(fields) => {
                let (x, y) = (g.tmp("(ref null $Slots)"), g.tmp("(ref null $Slots)"));
                g.line(&format!("(local.set {x} (ref.cast (ref null $Slots) (local.get 0)))"));
                g.line(&format!("(local.set {y} (ref.cast (ref null $Slots) (local.get 1)))"));
                for (i, (_, fty)) in fields.iter().enumerate() {
                    let eq = g.eq_fn(fty, span);
                    g.line(&format!("(if (i32.eqz (call {eq} (array.get $Slots (local.get {x}) (i32.const {i})) (array.get $Slots (local.get {y}) (i32.const {i})))) (then (return (i32.const 0))))"));
                }
                g.line("i32.const 1");
            }
            _ => {
                let what = g.not_compiled(ty, "comparing values whose type is a generic parameter");
                g.diags.push(Diagnostic::error(codes::NOT_COMPILED_YET, what, span));
                g.line("i32.const 0");
            }
        });
        self.emit_helper(&format!("(func {name} (type $EqF)"), body);
        name
    }

    /// The `$HashF` for map keys and set items of `ty`.
    fn hash_fn(&mut self, ty: &Ty, span: Span) -> String {
        if self.is_string(ty) {
            return "$k_str_hash".into();
        }
        match self.wt(ty).as_deref() {
            Some("i64") => return "$k_hash_int".into(),
            Some("i32") => return "$k_hash_bool".into(),
            Some("f64") => return "$k_hash_float".into(),
            _ => {}
        }
        let (name, fresh) = self.helper(format!("hash:{ty:?}"), "hash");
        if !fresh {
            return name;
        }
        let body = self.in_helper(|g| match g.parts(ty) {
            Some(Parts::Opt(inner)) => {
                let h = g.hash_fn(&inner, span);
                g.line("local.get 0");
                g.line("ref.is_null");
                g.line("if (result i64)");
                g.line("i64.const 0");
                g.line("else");
                g.line("i64.const 1");
                g.line(&format!("(call {h} (struct.get $Opt 0 (ref.cast (ref $Opt) (local.get 0))))"));
                g.line("call $k_hash_combine");
                g.line("end");
            }
            Some(Parts::List(item)) => {
                let h = g.hash_fn(&item, span);
                let (x, i, r) = (g.tmp("(ref null $List)"), g.tmp("i32"), g.tmp("i64"));
                g.line(&format!("(local.set {x} (ref.cast (ref null $List) (local.get 0)))"));
                g.line(&format!("(local.set {r} (i64.extend_i32_s (call $k_len (local.get {x}))))"));
                g.line(&format!("(block $done (loop $next (br_if $done (i32.ge_s (local.get {i}) (call $k_len (local.get {x})))) (local.set {r} (call $k_hash_combine (local.get {r}) (call {h} (call $k_item (local.get {x}) (local.get {i}))))) (local.set {i} (i32.add (local.get {i}) (i32.const 1))) (br $next)))"));
                g.line(&format!("local.get {r}"));
            }
            Some(Parts::Fields(fields)) => {
                let r = g.tmp("i64");
                for (access, fty) in fields {
                    let h = g.hash_fn(&fty, span);
                    g.line(&format!("local.get {r}"));
                    g.line(&access);
                    g.line(&format!("call {h}"));
                    g.line("call $k_hash_combine");
                    g.line(&format!("local.set {r}"));
                }
                g.line(&format!("local.get {r}"));
            }
            Some(Parts::Enum(variants)) => {
                let (x, r) = (g.tmp("(ref null $Enum)"), g.tmp("i64"));
                g.line(&format!("(local.set {x} (ref.cast (ref null $Enum) (local.get 0)))"));
                g.line(&format!("(local.set {r} (call $k_hash_mix (i64.extend_i32_u (struct.get $Enum 0 (local.get {x})))))"));
                for (i, fields) in variants.into_iter().enumerate() {
                    if fields.is_empty() {
                        continue;
                    }
                    g.line(&format!("(if (i32.eq (struct.get $Enum 0 (local.get {x})) (i32.const {i})) (then"));
                    for (j, fty) in fields.into_iter().enumerate() {
                        let h = g.hash_fn(&fty, span);
                        g.line(&format!("(local.set {r} (call $k_hash_combine (local.get {r}) (call {h} (array.get $Slots (struct.get $Enum 1 (local.get {x})) (i32.const {j})))))"));
                    }
                    g.line("))");
                }
                g.line(&format!("local.get {r}"));
            }
            None => {
                let what = g.not_compiled(ty, "a map key or set item of this type");
                g.diags.push(Diagnostic::error(codes::NOT_COMPILED_YET, what, span));
                g.line("i64.const 0");
            }
        });
        self.emit_helper(&format!("(func {name} (type $HashF)"), body);
        name
    }

    /// A `$CmpF` that orders values of `ty`, as the C backend's `cmp_fn`.
    fn cmp_fn(&mut self, ty: &Ty, span: Span) -> String {
        let (name, fresh) = self.helper(format!("cmp:{ty:?}"), "cmp");
        if !fresh {
            return name;
        }
        let body = self.in_helper(|g| {
            if g.is_string(ty) {
                g.line("(extern.convert_any (local.get 0))");
                g.line("(extern.convert_any (local.get 1))");
                g.line("call $k_str_cmp");
                return;
            }
            if let Some(w @ ("i64" | "f64" | "i32")) = g.wt(ty).as_deref() {
                {
                    let (lt, gt) = match w {
                        "i64" => ("i64.lt_s", "i64.gt_s"),
                        "f64" => ("f64.lt", "f64.gt"),
                        _ => ("i32.lt_u", "i32.gt_u"),
                    };
                    let (x, y) = (g.tmp(w), g.tmp(w));
                    g.line("local.get 0");
                    g.unslot(ty);
                    g.line(&format!("local.set {x}"));
                    g.line("local.get 1");
                    g.unslot(ty);
                    g.line(&format!("local.set {y}"));
                    g.line(&format!("(if (result i32) ({lt} (local.get {x}) (local.get {y})) (then (i32.const -1)) (else ({gt} (local.get {x}) (local.get {y}))))"));
                    return;
                }
            }
            match g.parts(ty) {
                Some(Parts::Opt(inner)) => {
                    let c = g.cmp_fn(&inner, span);
                    g.line("(i32.or (ref.is_null (local.get 0)) (ref.is_null (local.get 1)))");
                    g.line("if (result i32)");
                    g.line("(i32.sub (i32.eqz (ref.is_null (local.get 0))) (i32.eqz (ref.is_null (local.get 1))))");
                    g.line("else");
                    g.line(&format!("(call {c} (struct.get $Opt 0 (ref.cast (ref $Opt) (local.get 0))) (struct.get $Opt 0 (ref.cast (ref $Opt) (local.get 1))))"));
                    g.line("end");
                }
                Some(Parts::List(item)) => {
                    let c = g.cmp_fn(&item, span);
                    let (x, y, i, r) = (
                        g.tmp("(ref null $List)"),
                        g.tmp("(ref null $List)"),
                        g.tmp("i32"),
                        g.tmp("i32"),
                    );
                    g.line(&format!("(local.set {x} (ref.cast (ref null $List) (local.get 0)))"));
                    g.line(&format!("(local.set {y} (ref.cast (ref null $List) (local.get 1)))"));
                    g.line(&format!("(block $done (loop $next (br_if $done (i32.or (i32.ge_s (local.get {i}) (call $k_len (local.get {x}))) (i32.ge_s (local.get {i}) (call $k_len (local.get {y}))))) (local.set {r} (call {c} (call $k_item (local.get {x}) (local.get {i})) (call $k_item (local.get {y}) (local.get {i})))) (if (local.get {r}) (then (return (local.get {r})))) (local.set {i} (i32.add (local.get {i}) (i32.const 1))) (br $next)))"));
                    g.line(&format!("(if (result i32) (i32.lt_s (call $k_len (local.get {x})) (call $k_len (local.get {y}))) (then (i32.const -1)) (else (i32.gt_s (call $k_len (local.get {x})) (call $k_len (local.get {y})))))"));
                }
                Some(Parts::Fields(fields)) => {
                    let r = g.tmp("i32");
                    for (access, fty) in fields {
                        let c = g.cmp_fn(&fty, span);
                        let other = access.replace("(local.get 0)", "(local.get 1)");
                        g.line(&format!("(local.set {r} (call {c} {access} {other}))"));
                        g.line(&format!("(if (local.get {r}) (then (return (local.get {r}))))"));
                    }
                    g.line("i32.const 0");
                }
                Some(Parts::Enum(variants)) => {
                    let (x, y, r) = (g.tmp("(ref null $Enum)"), g.tmp("(ref null $Enum)"), g.tmp("i32"));
                    g.line(&format!("(local.set {x} (ref.cast (ref null $Enum) (local.get 0)))"));
                    g.line(&format!("(local.set {y} (ref.cast (ref null $Enum) (local.get 1)))"));
                    g.line(&format!("(if (i32.ne (struct.get $Enum 0 (local.get {x})) (struct.get $Enum 0 (local.get {y}))) (then (return (select (i32.const -1) (i32.const 1) (i32.lt_s (struct.get $Enum 0 (local.get {x})) (struct.get $Enum 0 (local.get {y})))))))"));
                    for (i, fields) in variants.into_iter().enumerate() {
                        if fields.is_empty() {
                            continue;
                        }
                        g.line(&format!("(if (i32.eq (struct.get $Enum 0 (local.get {x})) (i32.const {i})) (then"));
                        for (j, fty) in fields.into_iter().enumerate() {
                            let c = g.cmp_fn(&fty, span);
                            g.line(&format!("(local.set {r} (call {c} (array.get $Slots (struct.get $Enum 1 (local.get {x})) (i32.const {j})) (array.get $Slots (struct.get $Enum 1 (local.get {y})) (i32.const {j}))))"));
                            g.line(&format!("(if (local.get {r}) (then (return (local.get {r}))))"));
                        }
                        g.line("))");
                    }
                    g.line("i32.const 0");
                }
                None => {
                    g.diags.push(Diagnostic::error(
                        codes::NOT_COMPILED_YET,
                        "sorting by a key of this type is not supported by the compiler yet",
                        span,
                    ));
                    g.line("i32.const 0");
                }
            }
        });
        self.emit_helper(&format!("(func {name} (type $CmpF)"), body);
        name
    }

    /// How a compound value breaks into parts, for hashing and ordering.
    /// A field's access is an expression that reads it as a slot from
    /// `(local.get 0)`.
    fn parts(&mut self, ty: &Ty) -> Option<Parts> {
        match ty {
            Ty::Opt(inner) => Some(Parts::Opt((**inner).clone())),
            Ty::Adt(id, args) if *id == self.prims.list => Some(Parts::List(args[0].clone())),
            Ty::Adt(id, args) if !self.p.is_prim(*id) => {
                let adt = self.p.adts[*id].clone();
                let map = self.type_map(*id, args);
                match &adt.kind {
                    AdtKind::Struct(fields) => {
                        let mut out = Vec::new();
                        for (i, f) in fields.iter().enumerate() {
                            let slot = self.slot_text(&f.ty);
                            let slot: Vec<&str> = slot.lines().map(str::trim).collect();
                            let mut access = format!(
                                "(struct.get $S{id} {i} (ref.cast (ref $S{id}) (local.get 0)))"
                            );
                            for op in slot {
                                access = format!("({op} {access})");
                            }
                            out.push((access, substitute(&f.ty, &map)));
                        }
                        Some(Parts::Fields(out))
                    }
                    AdtKind::Enum(variants) => Some(Parts::Enum(
                        variants
                            .iter()
                            .map(|v| v.fields.iter().map(|(_, t)| substitute(t, &map)).collect())
                            .collect(),
                    )),
                }
            }
            Ty::Record(fields) => Some(Parts::Fields(
                fields
                    .iter()
                    .enumerate()
                    .map(|(i, (_, t))| {
                        (
                            format!("(array.get $Slots (ref.cast (ref $Slots) (local.get 0)) (i32.const {i}))"),
                            t.clone(),
                        )
                    })
                    .collect(),
            )),
            _ => None,
        }
    }
}

/// The parts of a compound value, as [`Gen::parts`] gives them.
enum Parts {
    Opt(Ty),
    List(Ty),
    Fields(Vec<(String, Ty)>),
    Enum(Vec<Vec<Ty>>),
}

const EXIT_FAILED: &str = "
  ;; When `main` leaves with an error, says what it was.
  (func $k_exit_failed
    (if (global.get $failed)
      (then (call $k_fail_exit (call_ref $ShowF (global.get $error) (ref.as_non_null (global.get $error_show)))))))
";

fn default_value(wt: &str) -> String {
    match wt {
        "i64" => "i64.const 0".into(),
        "f64" => "f64.const 0".into(),
        "i32" => "i32.const 0".into(),
        "externref" => "ref.null extern".into(),
        "anyref" => "ref.null any".into(),
        w => {
            let heap = w
                .trim_start_matches("(ref null ")
                .trim_start_matches("(ref ")
                .trim_end_matches(')');
            format!("ref.null {heap}")
        }
    }
}

fn cell_type(wt: Option<&str>) -> &'static str {
    match wt {
        Some("i64") => "$CellI64",
        Some("f64") => "$CellF64",
        Some("i32") => "$CellI32",
        Some("externref") => "$CellExt",
        _ => "$CellAny",
    }
}

fn wat_float(x: f64) -> String {
    if x.is_nan() {
        "nan".into()
    } else if x.is_infinite() {
        if x > 0.0 {
            "inf".into()
        } else {
            "-inf".into()
        }
    } else {
        format!("{x:?}")
    }
}

/// A string in the text format.
pub(crate) fn wat_string(s: &str) -> String {
    let mut out = String::from("\"");
    for b in s.bytes() {
        match b {
            b'"' => out.push_str("\\\""),
            b'\\' => out.push_str("\\\\"),
            0x20..=0x7e => out.push(b as char),
            _ => {
                let _ = write!(out, "\\{b:02x}");
            }
        }
    }
    out.push('"');
    out
}

/// The type of a block's value.
fn block_ty(b: &Block) -> Ty {
    b.value.as_ref().map(|v| v.ty.clone()).unwrap_or(Ty::Unit)
}

/// Functions and globals an IR tree refers to.
#[derive(Default)]
struct Refs {
    funcs: Vec<FuncId>,
    globals: Vec<GlobalId>,
}

fn walk_block(b: &Block, r: &mut Refs) {
    for s in &b.stmts {
        walk_stmt(s, r);
    }
    if let Some(v) = &b.value {
        walk_expr(v, r);
    }
}

fn walk_stmt(s: &Stmt, r: &mut Refs) {
    match s {
        Stmt::Let(_, e) | Stmt::SetGlobal(_, e) | Stmt::SetStore(_, e) | Stmt::Expr(e) => {
            walk_expr(e, r)
        }
        Stmt::Assign { place, value, .. } => {
            match place {
                Place::Local(_) => {}
                Place::Field { base, .. } => walk_expr(base, r),
                Place::ListItem { list, index, .. } => {
                    walk_expr(list, r);
                    walk_expr(index, r);
                }
                Place::MapEntry { map, key } => {
                    walk_expr(map, r);
                    walk_expr(key, r);
                }
            }
            walk_expr(value, r);
        }
        Stmt::Return(e) => {
            if let Some(e) = e {
                walk_expr(e, r);
            }
        }
        Stmt::Break | Stmt::Continue => {}
        Stmt::While { cond, body } => {
            walk_expr(cond, r);
            walk_block(body, r);
        }
        Stmt::ForRange {
            lo,
            hi,
            filter,
            body,
            ..
        } => {
            walk_expr(lo, r);
            walk_expr(hi, r);
            if let Some(f) = filter {
                walk_expr(f, r);
            }
            walk_block(body, r);
        }
        Stmt::ForEach {
            iter, filter, body, ..
        } => {
            walk_expr(iter, r);
            if let Some(f) = filter {
                walk_expr(f, r);
            }
            walk_block(body, r);
        }
    }
}

fn walk_pattern(p: &Pattern, r: &mut Refs) {
    match p {
        Pattern::Literal(e) => walk_expr(e, r),
        Pattern::Some(inner, _) => walk_pattern(inner, r),
        Pattern::Variant { fields, .. } => {
            for (f, _) in fields {
                walk_pattern(f, r);
            }
        }
        _ => {}
    }
}

fn walk_expr(e: &Expr, r: &mut Refs) {
    match &e.kind {
        ExprKind::Global(g) => r.globals.push(*g),
        ExprKind::FuncRef(f) => r.funcs.push(*f),
        ExprKind::Closure { func, .. } => r.funcs.push(*func),
        ExprKind::Call { func, args } => {
            r.funcs.push(*func);
            for a in args {
                walk_expr(a, r);
            }
        }
        ExprKind::Concat(xs) | ExprKind::List(xs) | ExprKind::Record(xs) => {
            for x in xs {
                walk_expr(x, r);
            }
        }
        ExprKind::Struct { fields, .. } | ExprKind::Variant { fields, .. } => {
            for x in fields {
                walk_expr(x, r);
            }
        }
        ExprKind::Show(x)
        | ExprKind::Not(x)
        | ExprKind::Neg(x)
        | ExprKind::IsNone(x)
        | ExprKind::Print(x)
        | ExprKind::Env(x)
        | ExprKind::Panic(x)
        | ExprKind::Coerce(x)
        | ExprKind::Try { expr: x, .. }
        | ExprKind::Throw { value: x, .. } => walk_expr(x, r),
        ExprKind::Field { base, .. } => walk_expr(base, r),
        ExprKind::Arith(_, a, b)
        | ExprKind::Cmp(_, a, b)
        | ExprKind::Eq(a, b)
        | ExprKind::And(a, b)
        | ExprKind::Or(a, b)
        | ExprKind::Coalesce(a, b)
        | ExprKind::Range(a, b)
        | ExprKind::ListItem { list: a, index: b }
        | ExprKind::MapGet { map: a, key: b } => {
            walk_expr(a, r);
            walk_expr(b, r);
        }
        ExprKind::CallClosure { callee, args } => {
            walk_expr(callee, r);
            for a in args {
                walk_expr(a, r);
            }
        }
        ExprKind::Method { recv, args, .. } => {
            walk_expr(recv, r);
            for a in args {
                walk_expr(a, r);
            }
        }
        ExprKind::Lib { args, .. } | ExprKind::Log { args, .. } => {
            for a in args {
                walk_expr(a, r);
            }
        }
        ExprKind::If {
            cond,
            then,
            otherwise,
        } => {
            walk_expr(cond, r);
            walk_block(then, r);
            if let Some(o) = otherwise {
                walk_block(o, r);
            }
        }
        ExprKind::Match { scrutinee, arms } => {
            walk_expr(scrutinee, r);
            for arm in arms {
                walk_pattern(&arm.pattern, r);
                if let Some(g) = &arm.guard {
                    walk_expr(g, r);
                }
                walk_expr(&arm.body, r);
            }
        }
        ExprKind::Is { value, pattern } => {
            walk_expr(value, r);
            walk_pattern(pattern, r);
        }
        ExprKind::Block(b) => walk_block(b, r),
        ExprKind::Catch { expr, handler, .. } => {
            walk_expr(expr, r);
            walk_block(handler, r);
        }
        ExprKind::Int(_)
        | ExprKind::Float(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::None
        | ExprKind::Local(_)
        | ExprKind::StoreSlot(_)
        | ExprKind::NewMap
        | ExprKind::Error => {}
    }
}
